  $RUN argus-atlas chunk --tile 10/1012/638 --recipe antique --dem /data/dem/cook-strait_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/cook-strait/water.geojson --layer rivers=/data/dem/osm/cook-strait/rivers.geojson --layer roads=/data/dem/osm/cook-strait/roads.geojson --layer forest=/data/dem/osm/cook-strait/forest.geojson --layer urban=/data/dem/osm/cook-strait/urban.geojson --out /data/out/atlas/areas/cook-strait/antique/antique-10-1012-638
